-- Generated macro templates; all final bodies must fit 255 characters.
FeralSetupDefaults={
  ["cat"]="3",
  ["bear"]="1",
  ["aquatic"]="2",
  ["travel"]="4",
  ["bearSpell"]="Bear Form",
  ["bearCharge"]="Feral Charge",
  ["poison"]="Cure Poison",
  ["trinket"]="13",
  ["bandage"]="Your current bandage",
  ["interface"]="16001",
}
FeralSetupMacros={
  {name="Rejuvenation",body="#showtooltip Rejuvenation\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Rejuvenation"},
  {name="Regrowth",body="#showtooltip Regrowth\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Regrowth"},
  {name="Healing Touch",body="#showtooltip Healing Touch\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Healing Touch"},
  {name="Remove Curse",body="#showtooltip Remove Curse\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Remove Curse"},
  {name="Poison Cleanse",body="#showtooltip {{poison}}\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] {{poison}}"},
  {name="Innervate",body="#showtooltip Innervate\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Innervate"},
  {name="Thorns",body="#showtooltip Thorns\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Thorns"},
  {name="Pounce",body="#showtooltip Pounce\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Pounce"},
  {name="Bash",body="#showtooltip Bash\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Bash"},
  {name="Cat Charge",body="#showtooltip Feral Charge (Cat)\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Feral Charge (Cat)"},
  {name="Bear Charge",body="#showtooltip {{bearCharge}}\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] {{bearCharge}}"},
  {name="Faerie Fire",body="#showtooltip Faerie Fire\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Faerie Fire"},
  {name="Growl",body="#showtooltip Growl\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Growl"},
  {name="Roots",body="#showtooltip Entangling Roots\n/stopattack\n/cancelform [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead]\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Entangling Roots"},
  {name="Hibernate",body="#showtooltip Hibernate\n/stopattack\n/cancelform [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead]\n/cast [mod:shift,@focus,harm,nodead][mod:ctrl,@mouseover,harm,nodead][nomod,harm,nodead] Hibernate"},
  {name="Moonfire",body="#showtooltip Moonfire\n/cancelform [harm,nodead]\n/cast [harm,nodead] Moonfire"},
  {name="Rebirth",body="#showtooltip Rebirth\n/stopattack\n/cancelform [@mouseover,help,dead][help,dead]\n/cast [@mouseover,help,dead][help,dead] Rebirth"},
  {name="Tranquility",body="#showtooltip Tranquility\n/stopattack\n/cancelform\n/cast Tranquility"},
  {name="Prowl",body="#showtooltip Prowl\n/cast !Prowl"},
  {name="Maul",body="#showtooltip Maul\n/cast !Maul\n/startattack [harm,nodead]"},
  {name="Barkskin",body="#showtooltip Barkskin\n/stopcasting\n/cast Barkskin"},
  {name="Nature's Grasp",body="#showtooltip Nature's Grasp\n/stopcasting\n/stopattack\n/cast Nature's Grasp"},
  {name="Shadowmeld",body="#showtooltip Shadowmeld\n/stopcasting\n/stopattack\n/cast Shadowmeld"},
  {name="PvP Trinket",body="#showtooltip {{trinket}}\n/stopcasting\n/use {{trinket}}"},
  {name="Cat Form",body="#showtooltip Cat Form\n/stopcasting\n/cast [noform:{{cat}}] Cat Form"},
  {name="Bear Form",body="#showtooltip {{bearSpell}}\n/stopcasting\n/cast [noform:{{bear}}] {{bearSpell}}"},
  {name="Travel Forms",body="#showtooltip\n/stopcasting\n/cast [swimming,noform:{{aquatic}}] Aquatic Form; [noswimming,outdoors,noform:{{travel}}] Travel Form"},
  {name="Leave Form",body="/stopcasting\n/stopattack\n/cancelform"},
  {name="Set Focus",body="/clearfocus [mod:cmd]\n/stopmacro [mod]\n/focus [@mouseover,exists,nodead][exists,nodead]"},
  {name="Mark of the Wild",body="#showtooltip Mark of the Wild\n/stopmacro [mod:shift,nomod:cmd][mod:ctrl,nomod:cmd,@mouseover,nohelp][mod:ctrl,nomod:cmd,@mouseover,dead]\n/stopattack\n/cancelform\n/cast [mod:cmd,@player][@mouseover,help,nodead][help,nodead][@player] Mark of the Wild"},
}
